  spatialPanning?: boolean
  /** Minimum velocity threshold (px/ms) required to trigger sound (default: 0.04). */
  minVelocity?: number
  /** Velocity in px/ms mapped to max modulation (default: 2.0). */
  maxVelocity?: number
  /** Output pitch multiplier range [min, max] based on pointer speed (default: [0.95, 1.3]). */
  pitchRange?: [number, number]
  /** Biquad filter cutoff frequency range [minHz, maxHz] based on pointer speed (default: [500, 2400]). */
  cutoffRange?: [number, number]
  /** Idle timeout in milliseconds before stopping air sound after pointer halts (default: 85ms). */
  idleTimeoutMs?: number
  /** Whether cursor audio tracking is disabled. */
  disabled?: boolean
}

UseCursorSoundReturn.rawDefinition:
export interface UseCursorSoundReturn {
  state: {
    /** Whether the pointer is actively moving above the velocity threshold. */
    isMoving: boolean
    /** Whether the pointer is hovering inside the target container. */
    isHovering: boolean
    /** Real-time smoothed cursor velocity (px/ms). */
    cursorSpeed: number
    /** Normalized cursor coordinates and accumulated distance. */
    cursorPosition: CursorPosition
  }
  actions: {
    /** Ref callback to attach to a container element. */
    containerRef: (node: HTMLElement | null) => void
    /** Explicit manual stop helper. */
    stop: () => void
  }
  helpers: {
    /** Whether cursor motion tracking is active and ready. */
    isActive: boolean
  }
  ariaProps: {
    /** Indicates active cursor tracking sound feedback. */
    'data-sound-cursor': boolean
  }
  /** Pointer event handlers to spread onto any interactive element. */
  cursorProps: {
    onPointerEnter: (e: React.PointerEvent<HTMLElement>) => void
    onPointerMove: (e: React.PointerEvent<HTMLElement>) => void
    onPointerLeave: (e: React.PointerEvent<HTMLElement>) => void
  }

  // Direct top-level accessors
  isMoving: boolean
  isHovering: boolean
  cursorSpeed: number
  cursorPosition: CursorPosition
  containerRef: (node: HTMLElement | null) => void
  stop: () => void
}

UseDragSoundOptions.rawDefinition:
export interface UseDragSoundOptions {
  /** Sound cue identifier for continuous drag movement (default: 'navigate'). */
  cue?: SoundName
  /** Sound variant for drag movement (default: 'slide', options: 'slide', 'swipe', 'whoosh', 'default'). */
  variant?: string
  /** Sound dynamic emphasis level ('subtle' | 'normal' | 'strong'). */
  emphasis?: SoundEmphasis
  /** Base master volume multiplier (0.0 to 1.0). */
  volume?: number
  /** Distance in pixels dragged between acoustic movement strides (default: 36px). */
  stepDistance?: number
  /** Minimum velocity threshold (px/ms) required to trigger drag audio (default: 0.02). */
  minVelocity?: number
  /** Velocity in px/ms mapped to maximum emphasis & speed scaling (default: 1.5). */
  maxVelocity?: number
  /** Whether to dynamically pan audio in stereo (-1.0 to 1.0) based on pointer horizontal position (default: true). */
  spatialPanning?: boolean

  /**
   * Sound cue played when picking up / initiating drag (default: { cue: 'open', variant: 'slide' }).
   * Set to false to disable pickup sound.
   */
  pickCue?: DragCueOption | false
  /**
   * Discrete one-shot sound cue fired on pointer drop/release (default: 'release').
   * Set to false to disable drop sound.
   */
  dropCue?: DragCueOption | false
  /**
   * Sound cue played when a drag & drop target resolves successfully (default: { cue: 'success', variant: 'harmonic' }).
   */
  successCue?: DragCueOption
  /**
   * Sound cue played when a drag & drop operation fails or is rejected (default: { cue: 'error', variant: 'buzz' }).
   */
  errorCue?: DragCueOption
  /**
   * Sound cue played when items are reordered, swapped, or shuffled (default: { cue: 'navigate', variant: 'swipe' }).
   */
  shuffleCue?: DragCueOption

  /** Whether drag sound is disabled. */
  disabled?: boolean
}

UseDragSoundReturn.rawDefinition:
export interface UseDragSoundReturn {
  state: {
    /** Whether a drag interaction is actively occurring. */
    isDragging: boolean
    /** Current smoothed drag velocity magnitude (px/ms). */
    dragSpeed: number
    /** Drag displacement coordinates and Euclidean distance. */
    dragPosition: DragPosition
    /** Number of whoosh / slide stride triggers during current drag session. */
    dragCount: number
  }
  actions: {
    /** Triggers the motion stride sound cue during continuous dragging. */
    playStride: (override?: DragCueOption) => void
    /** Triggers the pick-up sound cue. */
    playPick: (override?: DragCueOption) => void
    /** Triggers the drop sound cue. */
    playDrop: (override?: DragCueOption) => void
    /** Triggers the success sound cue for valid drop zones. */
    playSuccess: (override?: DragCueOption) => void
    /** Triggers the error sound cue for invalid drops / cancellation. */
    playError: (override?: DragCueOption) => void
    /** Triggers the shuffle / reorder sound cue when items swap. */
    playShuffle: (override?: DragCueOption) => void
    /** Resets drag position and stride metrics. */
    reset: () => void
    /** Explicit manual stop helper. */
    stop: () => void
  }
  helpers: {
    /** Whether drag sound is ready to synthesize. */
    isActive: boolean
  }
  ariaProps: {
    /** Indicates active dragging feedback. */
    'data-sound-dragging': boolean
  }
  /** Pointer event props to spread onto any draggable element. */
  dragProps: {
    onPointerDown: (e: React.PointerEvent<HTMLElement>) => void
    onPointerMove: (e: React.PointerEvent<HTMLElement>) => void
    onPointerUp: (e: React.PointerEvent<HTMLElement>) => void
    onPointerCancel: (e: React.PointerEvent<HTMLElement>) => void
  }

  // Direct top-level accessors
  isDragging: boolean
  dragSpeed: number
  dragPosition: DragPosition
  dragCount: number
  playStride: (override?: DragCueOption) => void
  playPick: (override?: DragCueOption) => void
  playDrop: (override?: DragCueOption) => void
  playSuccess: (override?: DragCueOption) => void
  playError: (override?: DragCueOption) => void
  playShuffle: (override?: DragCueOption) => void
  reset: () => void
  stop: () => void
}

UseDynamicSoundOptions.rawDefinition:
export interface UseDynamicSoundOptions {
  /** Sound cue identifier (default: 'cursor'). */
  cue?: SoundName
  /** Sound variant identifier. */
  variant?: string
  /** Sound emphasis dynamic level. */
  emphasis?: SoundEmphasis
  /** Initial volume level multiplier (0.0 to 1.0). */
  volume?: number
  /** Initial stereo panning position (-1.0 to +1.0). */
  pan?: number
  /** Time to live in milliseconds. */
  ttl?: number
  /** Release fade-out duration in seconds when stopped. */
  release?: number
  /** Whether to automatically start playing on component mount. */
  autoStart?: boolean
  /** Whether sound playback is disabled. */
  disabled?: boolean
  /** Callback fired when the sound starts playing. */
  onStart?: () => void
  /** Callback fired when the sound stops playing. */
  onStop?: () => void
}

UseDynamicSoundReturn.rawDefinition:
export interface UseDynamicSoundReturn {
  state: {
    /** Whether this continuous voice is currently active and synthesizing. */
    isPlaying: boolean
    /** Effective sound cue identifier. */
    cue: SoundName
    /** Effective sound variant if specified. */
    variant?: string
    /** Unique active voice instance ID if playing. */
    voiceId?: string
    /** Number of total active continuous sounds in the sound engine. */
    activeCount: number
  }
  actions: {
    /** Starts the continuous sound loop. Returns the live SoundHandle or null. */
    start: (overrideOptions?: SoundContinuousOptions) => SoundHandle | null
    /** Gracefully stops the sound with a smooth release fade-out curve. */
    stop: (releaseDuration?: number) => void
    /** Toggles playing state between start and stop. */
    toggle: () => void
    /** Dynamically adjusts volume level multiplier (0.0 to 1.0). */
    setVolume: (volume: number, rampDuration?: number) => void
    /** Dynamically adjusts pitch multiplier (e.g. 0.5 to 3.0). */
    setPitch: (pitchMultiplier: number, rampDuration?: number) => void
    /** Dynamically adjusts detune in cents (+/- cents). */
    setDetune: (cents: number, rampDuration?: number) => void
    /** Dynamically adjusts filter cutoff frequency in Hertz. */
    setCutoff: (frequencyHz: number, rampDuration?: number) => void
    /** Dynamically adjusts stereo pan position (-1.0 to 1.0). */
    setPan: (pan: number, rampDuration?: number) => void
    /** Dynamically adjusts pulse rate / speed multiplier. */
    setRate: (rateMultiplier: number, rampDuration?: number) => void
    /** Batch modulates multiple audio parameters simultaneously. */
    setModulation: (params: SoundModulationParams, rampDuration?: number) => void
  }
  helpers: {
    /** Whether dynamic sound is ready to synthesize. */
    isReady: boolean
    /** Effective sound cue name. */
    cueName: SoundName
  }
  ariaProps: {
    /** Indicates active parametric sound modulation. */
    'aria-busy': boolean
    /** Data attribute signaling dynamic sound loop active state. */
    'data-sound-dynamic': boolean
    /** Sound cue identifier. */
    'data-sound-cue': string
  }
  /** Live SoundHandle reference if currently playing. */
  handle: SoundHandle | null
}

UseKeySoundOptions.rawDefinition:
export interface UseKeySoundOptions {
  /** Sound emphasis intensity level (default 'normal'). */
  emphasis?: SoundEmphasis
  /** Volume multiplier (0.0 to 1.0). */
  volume?: number
  /** Whether typing sounds are disabled. */
  disabled?: boolean
  /** Minimum interval in milliseconds between keystroke sounds (default 35ms). */
  rateLimitMs?: number
}

UseKeySoundReturn.rawDefinition:
export interface UseKeySoundReturn {
  state: {
    /** Whether keyboard sound is active and enabled. */
    isActive: boolean
    /** Last recognized key role. */
    lastKeyRole: SoundKeyRole | null
    /** Keystroke count during current session. */
    keystrokeCount: number
  }
  actions: {
    /** Keydown event handler to attach to text inputs, textareas, or editors. */
    handleKeyDown: (e: React.KeyboardEvent) => void
    /** Manual typing sound trigger. */
    triggerKeySound: (keyRole?: SoundKeyRole) => void
    /** Reset keystroke counter. */
    resetCounter: () => void
  }
  helpers: {
    /** Determines key role category for a given key string. */
    getKeyRole: (key: string) => SoundKeyRole
  }
  ariaProps: {
    'data-sound-typing': boolean
  }
}

UseScrollSoundOptions.rawDefinition:
export interface UseScrollSoundOptions {
  /** Sound cue identifier to modulate (default: 'toggle'). */
  cue?: SoundName
  /** Sound variant identifier (default: 'latch', options: 'latch', 'switch', 'mechanical', 'default'). */
  variant?: string
  /** Sound dynamic emphasis level ('subtle' | 'normal' | 'strong'). */
  emphasis?: SoundEmphasis
  /** Base master volume multiplier (0.0 to 1.0). */
  volume?: number
  /** Distance in pixels scrolled per acoustic latch step/click (default: 28px). */
  stepDistance?: number
  /** Minimum velocity threshold (px/ms) required to trigger audio (default: 0.03). */
  minVelocity?: number
  /** Velocity in px/ms mapped to maximum emphasis & speed scaling (default: 1.8). */
  maxVelocity?: number
  /** Idle timeout in milliseconds after which scroll state resets (default: 90ms). */
  idleTimeoutMs?: number
  /** Whether scroll sound is disabled. */
  disabled?: boolean
}

UseScrollSoundReturn.rawDefinition:
export interface UseScrollSoundReturn {
  state: {
    /** Whether the user is actively scrolling. */
    isScrolling: boolean
    /** Real-time smoothed scroll velocity magnitude (px/ms). */
    velocity: number
    /** Normalized speed factor (0.0 to 1.0+). */
    normalizedSpeed: number
    /** Total accumulated scrolled distance in pixels. */
    scrolledDistance: number
    /** Current vertical scroll direction. */
    direction: 'up' | 'down' | 'none'
    /** Current vertical scroll progress ratio (0.0 at top to 1.0 at bottom). */
    scrollProgress: number
    /** Total step latch count triggered during scroll session. */
    latchCount: number
  }
  actions: {
    /** Container ref callback to attach directly to a scrollable HTML element. */
    containerRef: (node: HTMLElement | null) => void
    /** Manual scroll event handler for virtualized or custom lists. */
    onScroll: (e: React.UIEvent<HTMLElement> | Event) => void
    /** Resets distance and latch counters. */
    reset: () => void
  }
  helpers: {
    /** Whether scroll sound tracking is active and ready. */
    isActive: boolean
  }
  ariaProps: {
    /** Indicates active user scrolling feedback. */
    'data-sound-scrolling': boolean
  }

  // Top-level direct accessors
  isScrolling: boolean
  velocity: number
  normalizedSpeed: number
  scrolledDistance: number
  direction: 'up' | 'down' | 'none'
  scrollProgress: number
  latchCount: number
  containerRef: (node: HTMLElement | null) => void
  onScroll: (e: React.UIEvent<HTMLElement> | Event) => void
  reset: () => void
}

UseSoundFeedbackOptions.rawDefinition:
export interface UseSoundFeedbackOptions {
  /** Sound cue played when async task starts (default 'open'). */
  startCue?: SoundName
  /** Sound cue played when async task succeeds (default 'success'). */
  successCue?: SoundName
  /** Sound cue played when async task fails (default 'error'). */
  errorCue?: SoundName
  /** Emphasis level for feedback cues (default 'normal'). */
  emphasis?: SoundEmphasis
  /** Custom volume level multiplier. */
  volume?: number
}

UseSoundFeedbackReturn.rawDefinition:
export interface UseSoundFeedbackReturn {
  state: {
    /** Whether an async operation is currently executing with sound feedback. */
    isLoading: boolean
    /** Last execution result status. */
    status: 'idle' | 'loading' | 'success' | 'error'
    /** Last error object if rejected. */
    error: Error | null
  }
  actions: {
    /** Wraps an asynchronous Promise or function execution with automatic sound feedback. */
    withSound: <T>(promiseOrFn: Promise<T> | (() => Promise<T>)) => Promise<T>
    /** Reset status to idle. */
    reset: () => void
  }
  helpers: {
    /** Whether sound feedback is active and ready. */
    isReady: boolean
  }
  ariaProps: {
    'aria-busy': boolean
    'aria-live': 'polite' | 'assertive' | 'off'
  }
}

UseSoundTriggerOptions.rawDefinition:
export interface UseSoundTriggerOptions {
  /** Sound cue identifier to play upon trigger (default 'tap'). */
  cue?: SoundName
  /** Sound variant identifier (e.g. 'mechanical', 'soft', 'pluck'). */
  variant?: string
  /** Trigger interaction event modality: 'click' | 'press' | 'hover' | 'toggle' | 'custom'. */
  event?: 'click' | 'press' | 'hover' | 'toggle' | 'custom'
  /** Sound emphasis intensity level. */
  emphasis?: SoundEmphasis
  /** Custom volume level multiplier (0.0 to 1.0). */
  volume?: number
  /** Whether the sound trigger is disabled. */
  disabled?: boolean
  /** Callback fired before/after sound playback. */
  onTrigger?: () => void
}

UseSoundTriggerReturn.rawDefinition:
export interface UseSoundTriggerReturn {
  state: {
    /** Whether sound is currently enabled and unmuted in the provider. */
    isActive: boolean
    /** Whether trigger was recently invoked. */
    isTriggered: boolean
    /** Assigned sound cue. */
    cue: SoundName
    /** Assigned sound variant if any. */
    variant?: string
    /** Assigned emphasis level. */
    emphasis: SoundEmphasis
  }
  actions: {
    /** Imperatively fire the sound trigger. */
    trigger: (overrideOptions?: SoundPlayOptions) => void
    /** Event handler for click events. */
    handleClick: (e?: React.MouseEvent) => void
    /** Event handler for pointer down events. */
    handlePointerDown: (e?: React.PointerEvent) => void
    /** Event handler for pointer enter events. */
    handlePointerEnter: (e?: React.PointerEvent) => void
  }
  helpers: {
    /** Whether sound feedback will play when triggered. */
    canPlay: boolean
    /** Effective sound cue name. */
    cueName: string
  }
  ariaProps: {
    /** Indicates active sound feedback capability. */
    'data-sound-cue': string
  }
}

ThemeConfig.rawDefinition:
export interface ThemeConfig {
  /** Mode: 'light', 'dark', or 'system' (default: 'system'). */
  defaultTheme?: ThemeMode
  /** Initial preset ID (default: 'mono'). */
  preset?: string
  /** Initial corner curvature preset or CSS value (default: 'md'). */
  radius?: RadiusPreset | string
  /** Initial shadow elevation preset (default: 'subtle'). */
  shadow?: ShadowPreset | string
  /** Initial optical density preset or factor (default: 'normal'). */
  density?: DensityPreset | number
  /** Initial stroke border-width preset (default: 'standard'). */
  stroke?: StrokePreset | string
  /** Initial base font size preset or value (default: 'md'). */
  fontSize?: FontSizePreset | string
  /** Initial sans font family (default: 'Inter'). */
  fontFamily?: string
  /** Initial mono font family (default: 'Geist Mono'). */
  fontFamilyMono?: string
  /** Optional theme extenders injecting custom presets, tokens, and font catalogs. */
  extenders?: ThemeExtension[]
  /** Optional ad-hoc theme presets. */
  presets?: ThemePreset[]
  /** Optional token descriptors for dynamic editor discovery. */
  descriptors?: TokenDescriptor[]
  /** Direct token overrides applied on root. */
  tokens?: TokenMap | Partial<ThemeTokens>
  /** Custom storage key for localStorage persistence (default: 'consona-theme'). */
  storageKey?: string
}

ThemeScopeProps.rawDefinition:
export interface ThemeScopeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Lock this subtree to 'light' or 'dark' mode */
  mode?: 'light' | 'dark'
  /** Lock this subtree to a specific preset object or preset ID */
  preset?: string | ThemePreset
  /** Lock corner curvature token (e.g. 'none', 'sm', 'md', 'lg', 'full', or custom CSS length) */
  radius?: RadiusPreset | string
  /** Lock elevation/shadow token ('none', 'subtle', 'soft', 'strong') */
  shadow?: ShadowPreset | string
  /** Lock optical density token ('compact', 'normal', 'spacious', or multiplier number) */
  density?: DensityPreset | number
  /** Lock stroke border-width token ('flat', 'standard', 'bold', or custom CSS length) */
  stroke?: StrokePreset | string
  /** Custom token variable overrides locked to this subtree */
  tokens?: TokenMap
  /** Optional HTML tag or wrapper component (default: 'div') */
  as?: React.ElementType
  children?: React.ReactNode
}

ThemePreset.rawDefinition:
export interface ThemePreset {
  id: string
  label: string
  description?: string
  /** Swatch colors shown in the picker (usually primary / bg / accent). */
  preview?: string[]
  /** Tokens shared across both light and dark modes (radius, density, shadow, stroke, fonts, spacing, or any custom variable). */
  tokens?: TokenMap
  /** Mode-specific overrides (primarily colors and surface tints) */
  light: ThemeTokens
  dark: ThemeTokens
  /** Metadata for external tooling or categories */
  meta?: Record<string, unknown>
}
